(function(){
 'use strict';
 const $=id=>document.getElementById(id),C=window.Curriculum,B=window.BuildingModel,WP=window.WorldPhotos,CA=window.ClimateActions,CM=window.ClimateModel,CASES=window.CLIMATE_CASES,KEY='climate-village-classroom-v1';
 const paths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',drop:'<path d="M12 2C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-13Z"/><path d="M8 15c0 2 1 3 3 3"/>',water:'<path d="M2 8q3-4 6 0t6 0t8 0M2 13q3-4 6 0t6 0t8 0M2 18q3-4 6 0t6 0t8 0"/>',snow:'<path d="M12 2v20M3.4 7l17.2 10M3.4 17 20.6 7M8 4l4 4 4-4M8 20l4-4 4 4M3 11l5-1-1-5M21 13l-5 1 1 5M7 19l1-5-5-1M17 5l-1 5 5 1"/>',cold:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0Z"/><path d="M12 9v9m6-11h3m-3 4h3"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/><path d="m19 2 .5 2.5L22 5l-2.5.5L19 8l-.5-2.5L16 5l2.5-.5Z"/>',bin:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',fridge:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M5 10h14M8 5v2m0 6v4"/>',tree:'<path d="m12 2-7 9h4l-6 7h18l-6-7h4L12 2ZM12 18v4"/>',factory:'<path d="M3 21V10l6 3V8l6 4V3h4v18H3Z"/><path d="M6 17h2m4 0h2m3 0h1"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v9H3v-9ZM6 19v2m12-2v2M6 14h2m8 0h2"/>',bolt:'<path d="m14 2-10 12h7l-1 8 10-12h-7l1-8Z"/>',school:'<path d="m2 10 10-7 10 7M4 9v12h16V9M10 21v-7h4v7M7 11h1m8 0h1"/><circle cx="12" cy="9" r="1"/>',leaf:'<path d="M20 3C7 1 1 12 7 18s16-1 13-15ZM5 21 17 7"/>',home:'<path d="m2 11 10-9 10 9M5 9v13h14V9M10 22v-8h4v8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 4C8 2 5 2 2 3v17c3-1 6-1 10 1 4-2 7-2 10-1V3c-3-1-6-1-10 1v17"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4" ry="10"/><path d="M2 12h20M4 6h16M4 18h16"/>',rotate:'<path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3V7Z"/><circle cx="12" cy="13" r="4"/>'};
 Object.assign(paths,{tower:'<path d="M6 22V2h12v20M3 22h18M9 6h2m2 0h2M9 10h2m2 0h2M9 14h2m2 0h2M10 22v-4h4v4"/>',apartment:'<path d="M3 22V4h18v18M7 8h2m6 0h2M7 12h2m6 0h2M7 16h2m6 0h2M10 22v-4h4v4"/>',hospital:'<path d="M3 22V8h5V2h8v6h5v14M10 22v-5h4v5M12 5v7m-3-3h6"/>',shop:'<path d="M3 10v12h18V10M2 10l3-7h14l3 7M2 10q2 4 5 0 3 4 5 0 3 4 5 0 3 4 5 0M5 15h7v5H5m11 2v-7h3"/>'});
 window.AppIcons=Object.fromEntries(Object.entries(paths).map(([k,v])=>[k,'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+v+'</svg>']));
 const icon=k=>window.AppIcons[k]||window.AppIcons.book,hazardIcon={heat:'sun',drought:'drop',flood:'water',snow:'snow',cold:'cold',night:'moon'};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const initial=()=>({view:'home',hazard:'heat',strength:3,caseTab:'photo',topic:0,actionTab:'choose',events:[],recent:null,future:100,futureHazard:'heat',world:'canada',worldSeen:[],water:0,seaTool:'orbit',selectedBuilding:'home',showBuildingNames:true,buildings:B.normalize(C.BASE_BUILDINGS),seaRuns:[],place:'school',notes:{},evidence:[],done:[],name:'',group:'',presentation:false});
 let storageOK=true,state=initial();
 function safeString(s,max=3000){return typeof s==='string'?s.slice(0,max):'';}
 function normalize(raw){const d=initial();if(!raw||typeof raw!=='object')return d;d.name=safeString(raw.name,60);d.group=safeString(raw.group,10);d.hazard=CASES.some(c=>c.id===raw.hazard)?raw.hazard:'heat';d.events=CA.clean(raw.events);d.topic=Number.isInteger(raw.topic)?C.clamp(raw.topic,0,5):0;d.water=C.clamp(Number(raw.water)||0,0,10);d.strength=C.clamp(Number(raw.strength)||3,1,3);d.done=Array.isArray(raw.done)?raw.done.filter(x=>C.LESSONS.some(l=>l.id===x)):[];d.worldSeen=Array.isArray(raw.worldSeen)?raw.worldSeen.filter(x=>C.WORLDS.some(c=>c.id===x)):[];if(raw.notes&&typeof raw.notes==='object')for(const [k,v]of Object.entries(raw.notes)){if(/^[a-z0-9_]+$/i.test(k))d.notes[k]=safeString(v);}if(Array.isArray(raw.evidence))d.evidence=raw.evidence.slice(0,40).filter(e=>e&&typeof e.title==='string').map(e=>({id:safeString(e.id,100),title:safeString(e.title,180),text:safeString(e.text,1000),source:safeString(e.source,500),kind:safeString(e.kind,30)}));if(Array.isArray(raw.buildings))d.buildings=B.normalize(raw.buildings);d.selectedBuilding=B.PLACEABLE.includes(raw.selectedBuilding)?raw.selectedBuilding:'home';d.showBuildingNames=raw.showBuildingNames!==false;d.seaRuns=Array.isArray(raw.seaRuns)?raw.seaRuns.filter(r=>r&&Number.isFinite(r.water)&&Number.isFinite(r.flooded)).slice(0,30).map(r=>({water:C.clamp(r.water,0,10),flooded:C.clamp(r.flooded,0,24),total:C.clamp(Number(r.total)||7,0,24),layout:safeString(r.layout,50)})):[];return d;}
 try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved)state=normalize(saved);}catch(e){storageOK=false;}
 function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,view:'home',recent:null,presentation:false}));}catch(e){storageOK=false;}}
 let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600);}
 const note=(key,label,placeholder='알아낸 점을 내 말로 적어 보세요.')=>'<label class="field"><span>'+label+'</span><textarea data-note="'+key+'" placeholder="'+esc(placeholder)+'">'+esc(state.notes[key]||'')+'</textarea><small>이 기기에 자동으로 저장돼요.</small></label>';
 function sourceLinks(c){return '<div class="source-links">'+c.sources.map(s=>'<a target="_blank" rel="noopener noreferrer" href="'+esc(s.url)+'">'+esc(s.publisher+' · '+s.title)+' ↗</a>').join('')+'</div>';}
 function selectCase(){return CASES.find(c=>c.id===state.hazard)||CASES[0];}
 function completeButton(id){return '<button class="outline full" data-complete="'+id+'">'+icon('check')+' '+(state.done.includes(id)?'탐구 완료 · 다시 수정할 수 있어요':'이 탐구 마치기')+'</button>';}
 function bookmarkButton(kind,label='이 증거 담기'){return '<button class="primary full" data-evidence="'+kind+'">'+icon('book')+' '+label+'</button>';}
 function chart(ds,color){const max=ds.max||Math.max(...ds.values)*1.15,width=304,height=180,x0=33,y0=22,bottom=143,cw=width-x0-12,chartH=bottom-y0,barw=Math.min(46,cw/ds.values.length*.6);let s='<svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="'+esc(ds.title)+'">';for(let i=0;i<=4;i++){const y=bottom-chartH*i/4,v=max*i/4;s+='<line x1="'+x0+'" x2="296" y1="'+y+'" y2="'+y+'" stroke="#e9eee1"/><text x="27" y="'+(y+3)+'" font-size="8" fill="#8b977e" text-anchor="end">'+(+v.toFixed(1))+'</text>';}ds.values.forEach((v,i)=>{const xx=x0+cw*(i+.5)/ds.values.length,barh=v/max*chartH,lab=(ds.shortLabels||ds.labels)[i];s+='<rect x="'+(xx-barw/2)+'" y="'+(bottom-barh)+'" width="'+barw+'" height="'+barh+'" rx="4" fill="'+(i===0?'#b9c9a8':color)+'"/><text x="'+xx+'" y="'+(bottom-barh-7)+'" font-size="11" font-weight="700" fill="#3f624a" text-anchor="middle">'+v+'</text><text x="'+xx+'" y="160" font-size="'+(ds.values.length>4?7:8)+'" fill="#6e8162" text-anchor="middle">'+esc(lab)+'</text>';});return s+'<text x="0" y="12" font-size="8" fill="#7d8d72">단위: '+esc(ds.unit)+'</text></svg>';}
 function renderNav(){$('lessonNav').innerHTML=C.LESSONS.map(l=>'<button data-go="'+l.id+'" class="'+(state.view===l.id?'active':'')+'" '+(state.view===l.id?'aria-current="page"':'')+'><span>'+l.no+(state.done.includes(l.id)?' ✓':'')+'</span>'+l.title+'</button>').join('');$('evidenceCount').textContent=state.evidence.length;}
 function renderHome(){$('home').innerHTML='<div class="home-content"><div class="eyebrow"><i class="dot"></i> 작은 선택, 달라지는 내일</div><h1>기후가 바뀌면,<br><em>우리 마을은?</em></h1><p>같은 마을의 다른 미래를 만나 보세요.<br>자료를 찾고, 선택을 쌓고, 물을 높이며<br>기후와 우리 생활의 연결을 탐구해요.</p><div class="home-actions"><button class="primary lime" data-go="phenomena">탐구 시작하기 '+icon('arrow')+'</button><button class="glass-btn" data-guide>수업 순서 보기</button></div></div><div class="home-path"><h3>다섯 가지 질문으로 이어지는 탐구</h3>'+C.LESSONS.map(l=>'<button data-go="'+l.id+'"><b>'+l.no+'</b>'+l.title+(state.done.includes(l.id)?' ✓':'')+'</button>').join('')+'</div><div class="home-foot">개인 탐구 · 모둠 토의 · 기록지 저장　 /　 교과서 90~101쪽 연계 · 가상 마을</div>';}
 function tabs(items,current,attr){return '<div class="tabs">'+items.map(([id,label])=>'<button '+attr+'="'+id+'" class="'+(current===id?'active':'')+'">'+label+'</button>').join('')+'</div>';}
 function renderPhenomena(){const c=selectCase(),ds=c.datasets[0];let content='<div class="smallcaps">OBSERVE & FIND</div><h2>'+c.name+'의 단서</h2><p>'+esc(c.headline)+'</p>'+tabs([['photo','사진'],['data','그래프·표'],['write','내 생각']],state.caseTab,'data-case-tab');
 if(state.caseTab==='photo')content+='<button class="case-photo-button" data-photo="'+c.id+'" aria-label="사진 크게 보기"><img class="case-photo" src="assets/'+esc(c.photo.filename)+'" alt="'+esc(c.photo.alt_ko)+'"></button><p class="caption">'+esc(c.photo.caption_ko)+' · 눌러서 크게 보기</p>'+c.facts.slice(0,2).map(f=>'<div class="fact"><b>'+esc(f.title)+'</b><p>'+esc(f.text)+'</p></div>').join('')+'<div class="mini-note">'+esc(c.photo.context_note_ko)+'</div><button class="outline full" style="margin-top:14px" data-case-tab="data">수치 자료도 살펴보기 '+icon('arrow')+'</button>';
 if(state.caseTab==='data')content+='<span class="pill">'+esc(ds.type)+'</span><div class="chartbox"><h3>'+esc(ds.title)+'</h3>'+chart(ds,c.color)+'</div><table class="data-table"><thead><tr><th>지역·기간</th><th>수치 ('+esc(ds.unit)+')</th></tr></thead><tbody>'+ds.labels.map((s,i)=>'<tr><td>'+esc(s)+'</td><td>'+ds.values[i]+'</td></tr>').join('')+'</tbody></table><p class="caption">'+esc(ds.geography)+'<br>'+esc(ds.period)+'</p><p>'+esc(ds.note)+'</p><div class="mini-note warm">자료를 읽을 때: '+esc(ds.limit)+'</div>'+sourceLinks(c)+'<div class="btn-row"><button class="outline" data-csv="'+c.id+'">표 내려받기</button><button class="primary" data-evidence="case">수치 증거 담기</button></div>';
 if(state.caseTab==='write')content+='<div class="mini-note">'+esc(c.questions[0])+'</div>'+note('phenomena_'+c.id,'사진·수치로 알게 된 점','어느 자료에서 무엇을 찾았는지 수치를 넣어 적어 보세요.')+note('limits_'+c.id,'이 자료만으로 알기 어려운 점','어떤 자료를 더 살펴보면 좋을까요?')+'<p class="caption">하루의 날씨와 오랜 기간의 기후는 구별해요. 한 사건의 자료만으로 오랜 변화의 원인을 모두 알 수는 없어요.</p>'+completeButton('phenomena');
 content+='<label class="slider-label" for="strength">가상 마을의 현상 정도 <output>'+['','약하게','중간','심하게'][state.strength]+'</output></label><input id="strength" data-strength type="range" min="1" max="3" value="'+state.strength+'"><p class="caption">이 조절 막대는 관측 수치를 바꾸지 않아요. 장면의 차이를 관찰하는 모형이에요.</p>';$('panel').innerHTML=content;
 $('dock').innerHTML='<div class="dock-intro">현상 선택<br>6모둠 탐구</div>'+CASES.map(c=>dock(c.id,c.name,c.id===state.hazard,hazardIcon[c.id],'data-hazard',c.id==='night'?'확장 현상':'교과서 현상')).join('');
 $('sceneTools').innerHTML='<button data-case-tab="photo">'+icon('camera')+' 실제 사진</button><button data-case-tab="data">'+icon('book')+' 그래프·표</button><button data-go="life">생활 변화도 살펴보기 ↗</button>';
 $('sceneStatus').innerHTML='<div class="status-card"><small>지금 보는 장면</small><b>'+c.name+'의 가상 상황</b><p>'+(['heat','drought'].includes(c.id)?'더위·물 부족이 함께 나타난 상황을 표현했어요.':'모형 장면과 실제 사진을 구별해요.')+'</p></div>';
 }
 function dock(id,label,active,ic,attr,small=''){return '<button class="dock-item '+(active?'active':'')+'" '+attr+'="'+id+'" aria-pressed="'+active+'">'+icon(ic)+'<span>'+label+(small?'<small>'+small+'</small>':'')+'</span></button>';}
 function renderActions(){const t=CM.TOPICS[state.topic],counts=CA.counts(state.events),mine=counts[state.topic],s=C.score(state.events);let content='<div class="smallcaps">CHOOSE & COMPARE</div><h2>'+t.short+'</h2>'+tabs([['choose','행동 선택'],['history','쌓인 행동'],['future','두 미래']],state.actionTab,'data-action-tab');
 if(state.actionTab==='choose')content+=note('action_prediction','먼저 예상해요','이 행동이 계속되면 어떤 일이 일어날까요?')+'<button class="action-button" data-action="1"><b>+ '+esc(t.high)+'</b><small>배출이 늘거나 흡수가 줄어드는 선택 · 누르면 1회 추가</small></button><button class="action-button low" data-action="-1"><b>+ '+esc(t.low)+'</b><small>배출을 줄이거나 흡수를 돕는 선택 · 누르면 1회 추가</small></button><div class="action-counts"><div><b>'+mine.high+'</b><small>이 주제의 늘리는 선택</small></div><div><b>'+mine.low+'</b><small>이 주제의 줄이는 선택</small></div></div><p>'+esc(state.recent?.topic===state.topic&&state.recent.level<0?t.lowCause:t.cause)+'</p><div class="mini-note">'+esc(t.clue)+'</div><button class="primary full" style="margin-top:15px" data-action-tab="future">시간이 지난 두 미래 보기 '+icon('arrow')+'</button>';
 if(state.actionTab==='history')content+='<div class="sea-result"><div><b>'+state.events.length+'</b><small>전체 행동 횟수 / 최대 120회</small></div><div><b>'+state.events.filter(e=>e.level<0).length+'</b><small>줄이는 선택 횟수</small></div></div><p>다른 주제를 눌러도 이전 행동은 남아요. 새 선택은 기존 기록 뒤에 쌓입니다.</p><table class="data-table"><thead><tr><th>주제</th><th>늘리기 / 줄이기</th></tr></thead><tbody>'+CM.TOPICS.map((t,i)=>'<tr><td>'+t.short+'</td><td>'+counts[i].high+' / '+counts[i].low+'</td></tr>').join('')+'</tbody></table><h3>최근 행동</h3><ol class="event-list">'+state.events.slice(-12).map((e,i)=>'<li><span>'+(state.events.length-Math.min(12,state.events.length)+i+1)+'. '+CM.TOPICS[e.topic].short+'</span><b>'+(e.level>0?'늘리는 선택':'줄이는 선택')+'</b></li>').join('')+'</ol><div class="btn-row"><button class="outline" data-undo-action '+(!state.events.length?'disabled':'')+'>마지막 선택 취소</button><button class="outline" data-reset-actions>행동 실험 새로</button></div>';
 if(state.actionTab==='future')content+='<p>같은 출발점에서 같은 시간이 지난 두 마을을 비교해요. 내 선택 '+state.events.length+'회가 누적되어 있어요.</p><div class="slider-label"><label for="futureTime">시간 보내기</label><output id="futureValue">'+state.future+'%</output></div><input id="futureTime" data-future type="range" min="0" max="100" value="'+state.future+'"><div class="choice-list"><button data-future-hazard="heat" class="'+(state.futureHazard==='heat'?'active':'')+'">더위·물 부족</button><button data-future-hazard="flood" class="'+(state.futureHazard==='flood'?'active':'')+'">침수 피해 상황</button></div><div class="mini-note" style="margin-top:12px">'+(s.direction==='same'?'아직 기준과 같은 조건이에요. 행동을 선택하고 비교해 보세요.':s.direction==='higher'?'내 선택을 이어 간 경로에서는 온실가스가 기준보다 더 많이 쌓였어요.':'내 선택을 이어 간 경로에서는 온실가스가 기준보다 덜 쌓였어요. 이미 배출된 온실가스가 즉시 사라지는 것은 아니에요.')+'</div>'+note('action_observation','두 미래에서 달라진 점','운동장·작물·강·도로를 비교하고, 선택과 연결해 적어 보세요.')+bookmarkButton('actions','선택과 비교 결과 담기')+'<p class="caption">행동 횟수와 변화는 상대 비교를 위한 학습용 모형입니다. 실제 기온·연도·재해 발생 확률을 계산한 예측이 아니에요. 특정 행동 한 번이 특정 홍수를 일으킨다는 뜻도 아니에요.</p>'+completeButton('actions');
 $('panel').innerHTML=content;$('dock').innerHTML='<div class="dock-intro">행동 선택<br>모두 누적</div>'+CM.TOPICS.map((t,i)=>dock(i,t.name,i===state.topic,t.icon,'data-topic',counts[i].high+' ↑ · '+counts[i].low+' ↓')).join('');
 $('sceneTools').innerHTML='<button data-action-tab="choose" class="'+(state.actionTab==='choose'?'active':'')+'">동작 살펴보기</button><button data-action-tab="future" class="'+(state.actionTab==='future'?'active':'')+'">두 미래 비교</button><button data-all-actions="1">늘리는 선택 6회</button><button data-all-actions="-1">줄이는 선택 6회</button>';
 $('sceneStatus').innerHTML='<div class="status-card"><small>선택은 계속 쌓여요</small><b>전체 '+state.events.length+'회</b><p>늘리는 선택 '+state.events.filter(e=>e.level>0).length+'회 · 줄이는 선택 '+state.events.filter(e=>e.level<0).length+'회</p></div>'+(state.actionTab==='future'?'<div class="status-card"><small>내 경로의 온실가스 누적</small><b>기준보다 '+(s.direction==='higher'?'더 많음':s.direction==='lower'?'더 적음':'같음')+'</b><p>상대적인 차이를 나타낸 학습용 모형</p></div>':'');
 }
 function worldMap(){return '<svg class="world-map" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-label="피해 사례의 나라를 대략 표시한 세계지도"><defs><pattern id="grid" width="83.333" height="83.333" patternUnits="userSpaceOnUse"><path class="graticule" d="M83 0H0V83"/></pattern></defs><rect width="1000" height="500" rx="20" fill="#d1e3db"/><rect width="1000" height="500" fill="url(#grid)"/><path class="continent" d="m68 88 52-46 72-5 44 22 51-7 37 31-25 28-33 4-8 32-33 7-11 37-32 14-15-22-34-6-36-49-25-9Zm171 120 32 19 22 43 29 11 20 42-8 60-28 54-20-22-8-65-25-41 3-37-25-33Zm209-136 39-25 25 23 32-19 33 18 49-9 61 18 37-7 56 25 60-6 37 31 57 5 29 38-21 20-35-8-18 27-37-12-11 30-41-24-21 11-9 40-19 14-10-45-22-15-24 13-20-30-32 1-14-20-28 17-35-9-17-27-22 5-13-36-34 3Zm26 112 37-5 22 24 29 4 24 46-17 52-28 31-10 50-22-10-11-45-27-38-10-41Zm321 144 42-21 38 15 30 32-24 29-42 3-37-20Zm-449-299 39-17 25 20-17 26-30 6Z"/><text x="185" y="100">북아메리카</text><text x="300" y="330">남아메리카</text><text x="514" y="157">유럽</text><text x="510" y="285">아프리카</text><text x="756" y="145">아시아</text><text x="834" y="370">오세아니아</text></svg>';}
 function worldPhotoCaption(p){return '<span class="photo-kind">'+esc(p.kind)+'</span><p>'+esc(p.caption)+'</p><p class="photo-context">'+esc(p.note)+'</p><small>'+esc(p.dateLabel)+' · '+esc(p.creator)+' · '+esc(p.license)+'</small>';}
 function worldPhotoFigure(id){const p=WP[id];return '<figure class="world-photo"><button data-world-photo="'+id+'" aria-label="'+esc(p.alt)+' 크게 보기"><img src="assets/'+esc(p.file)+'" alt="'+esc(p.alt)+'"><span>사진 크게 보기 ↗</span></button><figcaption>'+worldPhotoCaption(p)+'<a href="'+esc(p.sourceUrl)+'" target="_blank" rel="noopener noreferrer">원본·출처 ↗</a></figcaption></figure>';}
 function worldPhotoModal(id){const p=WP[id],c=C.WORLDS.find(x=>x.id===id);if(!p||!c)return;showModal(modalTop('REAL WORLD · '+esc(p.kind),c.country+' 피해와 생활 모습')+'<img class="image-modal world-photo-large" src="assets/'+esc(p.file)+'" alt="'+esc(p.alt)+'"><div class="world-photo-credit">'+worldPhotoCaption(p)+'</div><div class="source-links"><a href="'+esc(p.sourceUrl)+'" target="_blank" rel="noopener noreferrer">사진 원본·저작자 정보 ↗</a><a href="'+esc(p.licenseUrl)+'" target="_blank" rel="noopener noreferrer">사진 재사용 조건 ↗</a></div>');}
 function buildingPicker(){showModal(modalTop('BUILD YOUR VILLAGE','어떤 건물을 놓을까요?')+'<p>건물을 고른 뒤 모형의 땅을 눌러 보세요. 같은 건물을 여러 개 놓을 수 있어요.</p><div class="building-grid">'+B.PLACEABLE.map(type=>{const t=B.TYPES[type];return '<button class="building-choice '+(state.selectedBuilding===type?'selected':'')+'" data-building-type="'+type+'" aria-pressed="'+(state.selectedBuilding===type)+'">'+B.preview(type)+'<b>'+t.name+'</b><span>'+t.description+'</span></button>';}).join('')+'</div><div class="mini-note">건물의 높이보다 땅의 높이를 먼저 비교해요. 높은 빌딩도 바닥부터 물에 잠길 수 있어요.</div>');}
 function renderSeverity(){const c=C.WORLDS.find(x=>x.id===state.world)||C.WORLDS[0];$('world').hidden=false;$('world').innerHTML='<div class="world-container">'+worldMap()+C.WORLDS.map((c,i)=>'<button class="world-pin '+(state.world===c.id?'active':'')+'" data-world="'+c.id+'" style="left:'+c.x+'%;top:'+c.y+'%" aria-label="'+c.country+' '+c.year+'년 '+c.hazard+' 사례">'+(state.worldSeen.includes(c.id)?'✓':i+1)+'<span>'+c.country+'</span></button>').join('')+'<div class="world-watermark">사례 위치를 대략 표시한 탐구용 지도 · 출처: 교과서 96~97쪽</div></div>';
 $('panel').innerHTML='<div class="smallcaps">GLOBAL CONNECTIONS</div><h2>'+c.country+' · '+c.year+'년</h2><span class="pill">'+c.hazard+'</span><h3 style="font-size:20px;line-height:1.7">'+c.title+'</h3>'+worldPhotoFigure(c.id)+'<div class="chain">'+c.clues.map((s,i)=>'<span>'+s+'</span>'+(i<c.clues.length-1?'<i>↓</i>':'')).join('')+'</div><p class="caption">교과서에 제시된 피해 사례를 읽기 쉽게 정리했어요. 개별 재해의 원인이 모두 같다는 뜻은 아니에요.</p><div class="mini-note">함께 생각해요<br>'+c.question+'</div>'+note('world_'+c.id,'피해와 심각성을 설명해요','어떤 생활이 어려워졌나요? 다른 나라의 사례와 어떤 공통점이 있나요?')+bookmarkButton('world','이 피해 사례 담기')+note('korea_case','우리나라에서 찾은 사례','장소·시기·피해·출처를 함께 적어 보세요.')+'<div class="source-links"><a href="https://wmo.int/publication-series/state-of-global-climate" target="_blank" rel="noopener noreferrer">세계기상기구(WMO) 기후 보고서 ↗</a><a href="https://www.kma.go.kr/kma/news/press.jsp" target="_blank" rel="noopener noreferrer">기상청 보도자료에서 국내 사례 찾기 ↗</a></div>'+completeButton('severity');
 $('dock').innerHTML='<div class="dock-intro">나라 선택<br>피해 연결</div>'+C.WORLDS.map(c=>dock(c.id,c.country,c.id===state.world,'globe','data-world',c.hazard)).join('');$('sceneTools').innerHTML='<button data-discussion>모둠 토의 질문</button><button data-world-photo="'+c.id+'">'+icon('camera')+' 사진 크게 보기</button><button data-go="phenomena">현상·수치 살펴보기</button>';$('sceneStatus').innerHTML='<div class="status-card"><small>살펴본 나라</small><b>'+state.worldSeen.length+' / 6곳</b><p>장소가 달라도 이어지는 생활 피해를 찾아요.</p></div>';
 }
 function renderSea(){const f=C.floodState(state.water,state.buildings),selected=B.TYPES[state.selectedBuilding];$('panel').innerHTML='<div class="smallcaps">PREDICT · TEST · OBSERVE</div><h2>해수면 입체 모형실험</h2><div class="mini-note">① 잠길 곳 예상 → ② 물 넣기 → ③ 관찰 기록 → ④ 건물 위치를 바꾸어 비교</div><div class="building-current">'+B.preview(state.selectedBuilding)+'<div><small>골라 놓을 건물</small><b>'+selected.name+'</b></div><button class="outline" data-building-picker>건물 고르기</button></div>'+note('sea_prediction','물을 넣기 전에 예상해요','어느 건물·길부터 물에 잠길까요? 그렇게 생각한 까닭은?')+'<label class="slider-label" for="waterLevel">물 높이 <output id="waterValue">'+state.water+'단계</output></label><input id="waterLevel" data-water type="range" min="0" max="10" step="1" value="'+state.water+'"><div class="btn-row"><button class="outline" data-water-step="-1" '+(state.water<=0?'disabled':'')+'>− 물 빼기</button><button class="primary" data-water-step="1" '+(state.water>=10?'disabled':'')+'>+ 물 넣기</button></div><div class="sea-result" style="margin-top:14px"><div><b id="wetBuildings">'+f.flooded+'</b><small>바닥이 물에 잠긴 건물</small></div><div><b>'+state.buildings.length+'</b><small>전체 건물</small></div></div><p class="caption">물이 건물 바닥보다 높아지면 침수로 세어요. 수조의 단계는 실제 바다의 cm나 특정 연도를 뜻하지 않아요.</p><button class="outline full" data-sea-run>이 높이의 관찰값 기록</button>'+(state.seaRuns.length?'<table class="data-table"><thead><tr><th>실험</th><th>물 단계 / 침수 건물</th></tr></thead><tbody>'+state.seaRuns.slice(-5).map((r,i)=>'<tr><td>'+(state.seaRuns.length-Math.min(5,state.seaRuns.length)+i+1)+'차</td><td>'+r.water+'단계 / '+r.flooded+'개</td></tr>').join('')+'</tbody></table>':'')+note('sea_observation','실험으로 알게 된 점','물을 높일 때와 건물 위치를 바꿀 때 무엇이 달라졌나요?')+bookmarkButton('sea','모형실험 결과 담기')+'<div class="btn-row"><button class="outline" data-sea-cause>왜 바닷물이 높아질까?</button><button class="outline" data-reset-sea>모형 처음으로</button></div><p class="caption">실제 수조·유토·종이 모형으로 하는 교과서 실험과 함께 사용할 수 있어요.</p>'+completeButton('sea');
 $('dock').innerHTML='<div class="dock-intro">모형 조작<br>놓기·돌리기</div>'+dock('orbit','화면 돌리기',state.seaTool==='orbit','rotate','data-sea-tool','마을을 드래그')+'<button class="dock-item" data-building-picker>'+icon('school')+'<span>건물 고르기<small>집·학교·빌딩 외 3종</small></span></button>'+dock(state.selectedBuilding,selected.name+' 놓기',state.seaTool===state.selectedBuilding,selected.icon,'data-sea-tool','땅을 눌러 여러 개 배치')+'<button class="dock-item" data-remove-building '+(!state.buildings.length?'disabled':'')+'>'+icon('rotate')+'<span>마지막 건물 취소</span></button>';
 $('sceneTools').innerHTML='<button data-zoom="-.15" aria-label="축소">−</button><button data-zoom=".15" aria-label="확대">+</button><button data-camera-reset>시점 처음으로</button><button data-toggle-building-names aria-pressed="'+state.showBuildingNames+'">건물 이름 '+(state.showBuildingNames?'켜짐':'꺼짐')+'</button><button data-sea-cause>실험 원리</button>';$('sceneStatus').innerHTML='<div class="status-card"><small>수조의 물 높이</small><b id="waterStatus">'+state.water+'단계 / 10단계</b><p>'+ (state.seaTool==='orbit'?'손가락으로 모형을 돌려 보세요.':'땅을 눌러 '+selected.name+' 배치 · 같은 건물도 여러 개 놓아요.')+'</p></div><div class="status-card"><small>처음 예상과 비교해요</small><b id="floodStatus">침수 건물 '+f.flooded+'개</b><p>건물의 모양과 땅의 높이를 함께 비교해요.</p></div>';

 }
 function renderLife(){const c=selectCase(),p=C.PLACES.find(p=>p.id===state.place)||C.PLACES[0],effects=p.effects[state.hazard];$('panel').innerHTML='<div class="smallcaps">CONNECT TO EVERYDAY LIFE</div><h2>'+p.name+'</h2><span class="pill">'+c.name+' 상황</span><h3>어떤 일이 이어질까요?</h3>'+effects.map((s,i)=>'<div class="impact-step"><i>'+(i+1)+'</i>'+s+'</div>').join('')+'<div class="choice-list" style="margin:15px 0">'+C.PLACES.map(p=>'<button data-place="'+p.id+'" class="'+(state.place===p.id?'active':'')+'">'+p.name+'</button>').join('')+note('life_'+state.hazard+'_'+state.place,'반복된다면 내 하루는 어떻게 달라질까요?','현상 → 직접 피해 → 생활 변화가 이어지게 설명해 보세요.')+note('life_response','피해를 줄이기 위해 필요한 일','우리의 배출을 줄이는 일과, 이미 생기는 피해에 대비하는 일을 함께 생각해 보세요.')+bookmarkButton('life','생활 연결 증거 담기')+'<button class="outline full" style="margin-top:10px" data-record>나의 탐구 기록지 보기</button>'+completeButton('life');$('dock').innerHTML='<div class="dock-intro">현상 선택<br>생활 연결</div>'+CASES.map(c=>dock(c.id,c.name,c.id===state.hazard,hazardIcon[c.id],'data-hazard')).join('');$('sceneTools').innerHTML='<button data-go="phenomena">실제 관측 자료 확인</button><button data-life-compare>전·후 장면 비교</button>';$('sceneStatus').innerHTML='<div class="status-card"><small>기후 현상</small><b>'+c.name+'</b></div><div class="status-card"><small>살펴보는 생활</small><b>'+p.name+'</b><p>장면의 장소를 눌러 바꿀 수도 있어요.</p></div>';
 }
 function render(){document.body.dataset.view=state.view;$('home').hidden=state.view!=='home';$('world').hidden=true;document.querySelectorAll('.future-legend,.divider3d').forEach(n=>n.remove());renderNav();if(state.view==='home'){renderHome();VillageScene.set(state);return;}const l=C.LESSONS.find(l=>l.id===state.view);$('sceneHead').innerHTML='<div class="eyebrow">'+l.no+'　'+l.pages+'</div><h1>'+l.question+'</h1><p>'+l.mission+'</p>';({phenomena:renderPhenomena,actions:renderActions,severity:renderSeverity,sea:renderSea,life:renderLife})[state.view]();VillageScene.set(state);if(state.view==='actions'&&state.actionTab==='future'){const el=document.createElement('div');el.className='future-legend';el.innerHTML='<div><b>기존 생활을 이어 간 마을</b><small>출발점과 흐른 시간은 같아요.</small></div><div><b>내 선택을 이어 간 마을</b><small>'+state.events.length+'회의 선택을 누적했어요.</small></div>';$('app').appendChild(el);}if(!storageOK&&$('panel'))$('panel').insertAdjacentHTML('beforeend','<p class="storage-warning">이 브라우저에서는 자동 저장을 사용할 수 없어요. 탐구 기록에서 백업 파일을 내려받아 주세요.</p>');}
 function go(view){if(view!=='home'&&!C.LESSONS.some(l=>l.id===view))return;state.view=view;if(view==='severity'&&!state.worldSeen.includes(state.world))state.worldSeen.push(state.world);if(view==='life')state.strength=3;save();render();if($('modal').open)$('modal').close();}
 function addAction(level,topic=state.topic){if(state.events.length>=120){toast('이번 실험의 120회가 모두 쌓였어요. 기록을 저장한 뒤 새 실험을 시작할 수 있어요.');return;}state.events.push({topic,level,id:'a-'+Date.now()+'-'+state.events.length});state.topic=topic;state.recent={topic,level,at:performance.now()};save();render();}
 function addEvidence(kind){let e;const c=selectCase();if(kind==='case'){const d=c.datasets[0];e={id:'case-'+c.id,kind,title:c.name+' · '+d.title,text:d.labels.map((l,i)=>l+': '+d.values[i]+d.unit).join(' / '),source:d.period+' · '+c.sources[0].publisher};}if(kind==='world'){const a=C.WORLDS.find(x=>x.id===state.world);e={id:'world-'+a.id,kind,title:a.country+' '+a.year+'년 '+a.hazard,text:a.clues.join(' → '),source:'과학 4-2 교과서 96~97쪽 · 사진 '+WP[a.id].dateLabel+' · '+WP[a.id].creator};}if(kind==='actions'){const s=C.score(state.events);e={id:'actions-'+state.events.length,kind,title:'누적 선택 '+state.events.length+'회 비교',text:CM.TOPICS.map((t,i)=>{const x=CA.counts(state.events)[i];return t.name+' 늘림 '+x.high+'회·줄임 '+x.low+'회';}).join(' / ')+' → 기준보다 온실가스 누적 '+(s.direction==='higher'?'많음':s.direction==='lower'?'적음':'같음'),source:'상대 비교용 학습 모형 · 실제 기후 예측 아님'};}if(kind==='sea'){const f=C.floodState(state.water,state.buildings);e={id:'sea-'+Date.now(),kind,title:'해수면 모형 '+state.water+'단계',text:'전체 '+f.total+'개 중 건물 바닥이 잠긴 건물 '+f.flooded+'개. '+(state.notes.sea_observation||''),source:'가상 수조 관찰 · 실제 지역 침수 예측 아님'};}if(kind==='life'){const p=C.PLACES.find(x=>x.id===state.place);e={id:'life-'+c.id+'-'+p.id,kind,title:c.name+'와 '+p.name,text:p.effects[c.id].join(' → '),source:'기후 현상으로 생길 수 있는 생활 영향'};}if(!e)return;if(state.evidence.some(x=>x.id===e.id)){toast('이미 담은 증거예요. 탐구 기록에서 확인하세요.');return;}if(state.evidence.length>=40){toast('증거는 40개까지 담을 수 있어요. 기록에서 필요한 증거를 골라 주세요.');return;}state.evidence.push(e);save();$('evidenceCount').textContent=state.evidence.length;toast('탐구 기록에 증거를 담았어요.');}
 function showModal(body){$('modalContent').innerHTML='<div class="modal-inner">'+body+'</div>';$('modal').showModal();}
 function modalTop(kicker,title){return '<div class="modal-top"><div><div class="smallcaps">'+kicker+'</div><h2>'+title+'</h2></div><button class="close" data-close aria-label="닫기">×</button></div>';}
 function guide(){showModal(modalTop('HOW TO EXPLORE','우리 마을을 탐구하는 방법')+'<p>자료를 관찰하고 예상한 뒤 직접 조작해 보세요. 알아낸 점은 내 말로 기록하고, 모둠 친구들과 근거를 비교해요.</p><div class="lesson-cards">'+C.LESSONS.map(l=>'<div class="lesson-card"><small>'+l.no+' · '+l.pages+'</small><b>'+l.title+'</b><p>'+l.mission+'</p><button data-go="'+l.id+'">여기서 시작</button></div>').join('')+'</div><div class="mini-note">마을 장면은 가상 상황을 표현한 그림이에요. 실제 사진·그래프는 01 현상 찾기의 ‘사진’과 ‘그래프·표’에서 확인해요. 기록은 현재 기기에 저장되며 친구 기기와 자동으로 합쳐지지 않아요.</div><div class="record-grid"><label class="field"><span>이름 (선택)</span><input data-profile="name" value="'+esc(state.name)+'" maxlength="60" placeholder="이름 없이도 사용할 수 있어요"></label><label class="field"><span>모둠 (선택)</span><select data-profile="group"><option value="">선택하지 않음</option>'+Array.from({length:6},(_,i)=>'<option '+(state.group===String(i+1)?'selected':'')+' value="'+(i+1)+'">'+(i+1)+'모둠</option>').join('')+'</select></label></div><div class="btn-row"><button class="outline" data-sources>자료·사진 출처</button><button class="primary" data-close>탐구 계속하기</button></div>');}
 function teacher(){showModal(modalTop('TEACHER TOOLS','수업 도구')+'<p>차시마다 필요한 메뉴로 바로 들어가세요. 6모둠은 폭염·가뭄·홍수·폭설·한파·열대야를 나누어 탐구할 수 있습니다. 모둠별 결과는 학생 기기에서 기록지로 저장하여 공유합니다.</p><div class="lesson-cards">'+C.LESSONS.map(l=>'<div class="lesson-card"><small>'+l.pages+'</small><b>'+l.title+'</b><p>예상·자료 확인 → 탐구 → 모둠 토의 → 설명</p><button data-go="'+l.id+'">이 탐구 열기</button></div>').join('')+'</div><div class="record-grid"><div><h3>함께 쓰는 타이머</h3><div id="timerNumber" class="timer-number">'+formatTime(timer.remaining)+'</div><div class="choice-list"><button data-timer-set="180">3분</button><button data-timer-set="300">5분</button><button data-timer-set="600">10분</button><button data-timer-set="1200">20분</button></div><div class="btn-row"><button class="primary" data-timer-toggle>'+(timer.running?'일시정지':'시작')+'</button><button class="outline" data-timer-reset>초기화</button></div><p class="caption">시작 버튼을 누르면 소리가 활성화돼요. 종료 5초 전부터 경고음, 종료 시 알림음이 나요.</p></div><div><h3>화면·토의</h3><button class="outline full" data-fullscreen>전체화면 전환</button><button class="outline full" style="margin-top:10px" data-discussion>토의 질문 크게 보기</button><button class="outline full" style="margin-top:10px" data-sources>자료·사진 출처</button><p class="caption">해수면 탐구는 실제 수조 모형실험의 예상·관찰 활동과 연결해서 사용하세요. 2050·2100년 특정 지역의 침수 예측을 보여 주는 앱은 아닙니다.</p></div></div>');}
 function discussion(){const l=C.LESSONS.find(l=>l.id===state.view),questions={phenomena:['사진만으로 알 수 있는 점과 수치가 필요한 점은 무엇일까요?','이 자료는 하루의 사건인가요, 오랜 기간의 변화인가요?'],actions:['어떤 선택을 얼마나 반복했나요?','두 미래의 차이를 온실가스 배출·흡수와 연결하면 어떻게 설명할 수 있을까요?'],severity:['서로 다른 나라에서 공통으로 어려워진 생활은 무엇인가요?','누가 더 큰 어려움을 겪을까요? 근거는 무엇인가요?'],sea:['어느 곳이 먼저 잠길 것이라고 예상했나요? 실제 모형 결과는 어땠나요?','물 높이를 그대로 두고 건물 위치를 바꾸면 무엇이 달라지나요?'],life:['자연의 변화가 내 하루에 어떤 순서로 영향을 주나요?','우리의 배출을 줄이는 일과 피해에 대비하는 일에는 어떤 것이 있나요?']};showModal(modalTop('TALK WITH EVIDENCE','모둠과 함께 생각해요')+'<p>'+esc(l?.title||'우리 마을 기후 탐구')+'</p>'+(questions[state.view]||questions.phenomena).map((q,i)=>'<div class="record-section" style="font-size:26px;line-height:1.7">'+(i+1)+'. '+q+'</div>').join('')+'<p>한 사람씩 근거를 말하고, 공통점과 다른 점을 찾아 설명을 다듬어 보세요.</p>');}
 function cause(){showModal(modalTop('WHY SEA LEVEL RISES','바닷물이 높아지는 까닭')+'<div class="record-grid"><div class="record-section"><h3>육지의 빙하가 녹으면</h3><svg viewBox="0 0 300 160" role="img" aria-label="육지의 얼음이 녹아 바다로 흘러가는 모형"><rect x="0" y="90" width="300" height="70" fill="#8ec5cb"/><path d="M0 160V48L89 25l66 135Z" fill="#aaa98c"/><path d="m0 49 89-24 20 30-34-10-30 22Z" fill="#eff8f4"/><path d="m96 66 35 36 45 4" fill="none" stroke="#eaf9ff" stroke-width="6"/><path d="m165 99 14 7-13 8" fill="none" stroke="#eaf9ff" stroke-width="4"/></svg><p>육지를 덮고 있던 얼음이 녹아 바다로 흘러들면 바닷물의 양이 늘어요.</p></div><div class="record-section"><h3>바닷물이 따뜻해지면</h3><svg viewBox="0 0 300 160" role="img" aria-label="따뜻해진 바닷물의 부피가 커지는 모형"><rect x="24" y="81" width="95" height="64" fill="#8ec5cb"/><rect x="180" y="52" width="95" height="93" fill="#8ec5cb"/><path d="M20 20v129h105V20M176 20v129h105V20" fill="none" stroke="#7a9a8b" stroke-width="3"/><path d="M137 98h28m-8-8 8 8-8 8" fill="none" stroke="#bd8157" stroke-width="3"/><circle cx="225" cy="22" r="13" fill="#e6b76e"/></svg><p>바닷물이 따뜻해지면 부피가 커져 해수면이 높아질 수 있어요. 그림의 높이 차이는 설명을 위해 크게 표현했어요.</p></div></div><div class="mini-note">바다에 이미 떠 있던 얼음과 육지에 있던 빙하는 구별해요. 이 앱의 수조는 물 높이가 달라질 때 나타나는 피해를 관찰하는 모형입니다.</div><div class="source-links"><a href="https://oceanservice.noaa.gov/facts/sealevel.html" target="_blank" rel="noopener noreferrer">미국 해양대기청(NOAA) · 해수면 상승의 원인 ↗</a></div>');}
 function sources(){showModal(modalTop('SOURCES & CREDITS','자료와 사진의 출처')+'<p>교과서: 천재교과서 『과학 4-2』(이상원), 4단원 90~101쪽. 앱은 교과서 내용을 바탕으로 활동을 재구성했으며 교과서 스캔을 재배포하지 않습니다.</p><div class="mini-note">실제 자료는 관측 지역·기간·단위가 서로 달라요. 모든 그래프가 장기 추세를 나타내는 것은 아닙니다. 한파·폭설이 지구 전체에서 똑같이 늘어난다고 해석하지 않도록 자료의 범위를 함께 살펴보세요.</div>'+CASES.map(c=>'<div class="record-section"><h3>'+c.name+'</h3>'+sourceLinks(c)+'<p class="caption">사진: '+esc(c.photo.display_creator||c.photo.creator)+' · '+esc(c.photo.license)+'<br>'+esc(c.photo.caption_ko)+'<br>표시 크기 조절·화면 잘림이 있을 수 있습니다.</p><div class="source-links"><a href="'+esc(c.photo.source_url)+'" target="_blank" rel="noopener noreferrer">사진 원본·저작자 ↗</a><a href="'+esc(c.photo.license_url)+'" target="_blank" rel="noopener noreferrer">사진 재사용 조건 ↗</a></div></div>').join('')+'<h2>세계 곳곳의 피해 사진</h2>'+C.WORLDS.map(c=>{const p=WP[c.id];return '<div class="record-section"><h3>'+c.country+'</h3><div class="world-photo-credit">'+worldPhotoCaption(p)+'</div><div class="source-links"><a href="'+esc(p.sourceUrl)+'" target="_blank" rel="noopener noreferrer">원본·저작자 ↗</a><a href="'+esc(p.licenseUrl)+'" target="_blank" rel="noopener noreferrer">재사용 조건 ↗</a></div></div>';}).join('')+'<p>마을의 정상·더위·침수·폭설 장면은 이 앱을 위해 생성한 가상 그림입니다. 사진·관측 기록과 구별하여 표시합니다. 수치 자료는 2026년 11월 확인본입니다.</p><div class="source-links"><a href="https://www.ipcc.ch/report/ar6/wg1/chapter/chapter-11/" target="_blank" rel="noopener noreferrer">IPCC · 기후변화와 극한 현상 ↗</a><a href="https://oceanservice.noaa.gov/facts/sealevel.html" target="_blank" rel="noopener noreferrer">NOAA · 해수면 상승 ↗</a></div>');}
 function sections(){const noteGroup=prefix=>Object.entries(state.notes).filter(([k,v])=>k.startsWith(prefix)&&v.trim()).map(([k,v])=>({key:k,text:v}));return [{title:'01 현상 찾기',texts:noteGroup('phenomena_').map(n=>(CASES.find(c=>'phenomena_'+c.id===n.key)?.name||'')+': '+n.text).concat(noteGroup('limits_').map(n=>'자료의 한계: '+n.text))},{title:'02 우리의 행동',texts:[state.notes.action_prediction?'예상: '+state.notes.action_prediction:'',state.events.length?'누적 행동 '+state.events.length+'회 (늘리는 선택 '+state.events.filter(e=>e.level>0).length+'회 / 줄이는 선택 '+state.events.filter(e=>e.level<0).length+'회)':'',state.notes.action_observation?'비교: '+state.notes.action_observation:''].filter(Boolean)},{title:'03 문제의 심각성',texts:noteGroup('world_').map(n=>(C.WORLDS.find(c=>'world_'+c.id===n.key)?.country||'')+': '+n.text).concat(state.notes.korea_case?['우리나라 사례: '+state.notes.korea_case]:[])},{title:'04 해수면 모형실험',texts:[state.notes.sea_prediction?'예상: '+state.notes.sea_prediction:'',...state.seaRuns.map((r,i)=>(i+1)+'차: '+r.water+'단계, '+r.total+'개 중 '+r.flooded+'개 침수'),state.notes.sea_observation?'관찰: '+state.notes.sea_observation:''].filter(Boolean)},{title:'05 생활의 변화',texts:noteGroup('life_').filter(n=>n.key!=='life_response').map(n=>{const [,hazard,place]=n.key.split('_');return (CASES.find(c=>c.id===hazard)?.name||'')+' · '+(C.PLACES.find(p=>p.id===place)?.name||'')+': '+n.text;}).concat(state.notes.life_response?['필요한 일: '+state.notes.life_response]:[])},{title:'내가 완성한 설명',texts:[state.notes.final||''].filter(Boolean)}];}
 function record(){showModal(modalTop('MY CLIMATE NOTEBOOK','나의 기후 탐구 기록')+'<div class="record-grid"><label class="field"><span>이름</span><input data-profile="name" maxlength="60" value="'+esc(state.name)+'" placeholder="이름 (선택)"></label><label class="field"><span>모둠</span><select data-profile="group"><option value="">선택하지 않음</option>'+Array.from({length:6},(_,i)=>'<option '+(state.group===String(i+1)?'selected':'')+' value="'+(i+1)+'">'+(i+1)+'모둠</option>').join('')+'</select></label></div><div class="badge-row">'+C.LESSONS.map(l=>'<span class="pill '+(state.done.includes(l.id)?'done':'')+'">'+(state.done.includes(l.id)?'✓ ':'')+l.title+'</span>').join('')+'</div><div class="record-grid">'+sections().slice(0,5).map(s=>'<div class="record-section"><h3>'+s.title+'</h3><p>'+esc(s.texts.join('\n\n')||'아직 적은 내용이 없어요. 탐구 메뉴에서 관찰과 생각을 기록해 보세요.')+'</p></div>').join('')+'</div>'+note('final','우리의 행동이 기후변화를 거쳐 생활에 주는 영향을 설명해요','내가 선택한 행동 → 기후와의 관계 → 관찰·자료 증거 → 생활 영향 → 필요한 일')+'<div class="record-section"><h3>내가 담은 증거 '+state.evidence.length+'개</h3>'+(state.evidence.length?state.evidence.map(e=>'<div class="evidence-item"><span><b>'+esc(e.title)+'</b><br>'+esc(e.text)+'</span><button data-delete-evidence="'+esc(e.id)+'">삭제</button></div>').join(''):'<p>자료·비교 결과·모형실험에서 ‘증거 담기’를 눌러 모아 보세요.</p>')+'</div><div class="btn-row print-hide"><button class="primary" data-export-png>기록지 이미지 저장</button><button class="outline" data-print>인쇄·PDF 저장</button><button class="outline" data-export-json>기록 백업</button><button class="outline" data-import-json>백업 불러오기</button></div><p class="caption print-hide">기록은 현재 브라우저에 저장됩니다. 다른 기기에서 이어 하려면 백업 파일을 내려받아 불러오세요. 이름과 기록은 서버로 전송하지 않습니다.</p>');}
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 async function exportPNG(){await document.fonts.ready;const cv=document.createElement('canvas'),x=cv.getContext('2d'),width=1400;const maxWidth=1180;let lines=[];function wrap(s,size){x.font=size+'px sans-serif';const words=String(s).split('\n');const out=[];for(const para of words){let line='';for(const ch of para){if(x.measureText(line+ch).width>maxWidth){out.push(line);line=ch;}else line+=ch;}out.push(line);}return out;}
 for(const sec of sections()){lines.push({kind:'title',text:sec.title});for(const t of sec.texts.length?sec.texts:['아직 기록하지 않았어요.'])for(const line of wrap(t,25))lines.push({kind:'body',text:line});lines.push({kind:'gap',text:''});}if(state.evidence.length){lines.push({kind:'title',text:'내가 담은 증거'});for(const e of state.evidence){for(const l of wrap(e.title+' — '+e.text,22))lines.push({kind:'evidence',text:l});for(const l of wrap('출처·범위: '+e.source,18))lines.push({kind:'source',text:l});lines.push({kind:'gap',text:''});}}
 cv.width=width;cv.height=Math.max(1980,670+lines.reduce((s,l)=>s+({title:65,body:42,gap:24,evidence:34,source:28}[l.kind]),0));if(cv.height>16000){toast('긴 기록은 인쇄·PDF 저장을 이용해 주세요.');return;}x.fillStyle='#f6f8ee';x.fillRect(0,0,width,cv.height);x.fillStyle='#174c43';x.fillRect(0,0,width,16);x.fillStyle='#6c8660';x.font='700 20px sans-serif';x.fillText('4학년 과학 · 기후 변화와 우리 생활',100,85);x.font='800 57px sans-serif';x.fillStyle='#214e3a';x.fillText('우리 마을 기후 탐구 기록',100,171);x.font='25px sans-serif';x.fillStyle='#6d825f';x.fillText((state.group?state.group+'모둠　':'')+(state.name||'이름: __________')+'　　'+new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul'}).format(new Date()),100,224);
 const hero=new Image();hero.src='assets/village.webp';try{await hero.decode();x.save();x.beginPath();x.roundRect(100,268,1200,240,18);x.clip();const scale=Math.max(1200/hero.naturalWidth,240/hero.naturalHeight),sw=1200/scale,sh=240/scale;x.drawImage(hero,(hero.naturalWidth-sw)/2,(hero.naturalHeight-sh)/2,sw,sh,100,268,1200,240);x.restore();}catch(e){}x.font='17px sans-serif';x.fillStyle='#849175';x.fillText('가상 마을 장면 · 실제 자료와 모형 결과를 구별하여 설명해요.',100,539);let y=605;for(const l of lines){if(l.kind==='title'){x.fillStyle='#214e3a';x.font='800 31px sans-serif';x.fillText(l.text,100,y);y+=65;}else if(l.kind==='gap')y+=24;else{x.fillStyle=l.kind==='source'?'#88967d':'#51674a';x.font=(l.kind==='body'?25:l.kind==='evidence'?22:18)+'px sans-serif';x.fillText(l.text,100,y);y+=l.kind==='body'?42:l.kind==='evidence'?34:28;}}cv.toBlob(blob=>{if(blob){download(blob,'우리마을_기후탐구기록.png');toast('탐구 기록지 이미지를 저장했어요.');}},'image/png');}
 function exportJSON(){download(new Blob([JSON.stringify({app:'climate-village-classroom',version:1,savedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),'기후탐구_백업.json');}
 function importJSON(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.style.display='none';document.body.append(input);input.addEventListener('cancel',()=>input.remove(),{once:true});input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>2e6){toast('2MB보다 작은 탐구 백업 파일을 골라 주세요.');return;}try{const raw=JSON.parse(await file.text());input.remove();if(raw.app!=='climate-village-classroom'||raw.version!==1||!raw.state)throw Error('wrong');showModal(modalTop('RESTORE NOTEBOOK','백업 기록 불러오기')+'<p>이 기기의 현재 기록을 선택한 백업 기록으로 바꿉니다. 현재 기록을 남기려면 먼저 백업하세요.</p><div class="btn-row"><button class="outline" data-export-json>현재 기록 백업</button><button class="primary" id="confirmImport">백업 기록으로 바꾸기</button></div>');$('confirmImport').onclick=()=>{state=normalize(raw.state);save();render();record();toast('백업 기록을 불러왔어요.');};}catch(e){toast('이 앱에서 저장한 JSON 백업 파일을 골라 주세요.');}};input.click();}
 const timer={remaining:300,initial:300,running:false,end:0,id:null,audio:null};function formatTime(t){return String(Math.floor(Math.max(0,t)/60)).padStart(2,'0')+':'+String(Math.max(0,t)%60).padStart(2,'0');}function beep(end=false){try{const a=timer.audio;if(!a)return;const n=end?3:1;for(let i=0;i<n;i++){const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=end?660:880;g.gain.setValueAtTime(0,a.currentTime+i*.35);g.gain.linearRampToValueAtTime(.35,a.currentTime+i*.35+.03);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+i*.35+.28);o.connect(g);g.connect(a.destination);o.start(a.currentTime+i*.35);o.stop(a.currentTime+i*.35+.3);}}catch(e){}}
 function paintTimer(){const text=formatTime(timer.remaining);if($('timerNumber'))$('timerNumber').textContent=text;let f=$('floatingTimer');if(!f&&timer.running){f=document.createElement('button');f.id='floatingTimer';f.className='timer-floating';f.onclick=teacher;document.body.append(f);}if(f){f.textContent=text;f.classList.toggle('warning',timer.remaining<=5);if(!timer.running&&timer.remaining>0)f.remove();}}
 function tick(){const old=timer.remaining;timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if(old!==timer.remaining&&timer.remaining<=5&&timer.remaining>0)beep();if(timer.remaining===0){timer.running=false;clearInterval(timer.id);beep(true);toast('탐구 시간이 끝났어요. 모둠과 관찰을 나누어 보세요.');}paintTimer();}
 function toggleTimer(){if(timer.running){timer.running=false;clearInterval(timer.id);paintTimer();}else{if(!timer.remaining)timer.remaining=timer.initial;try{timer.audio=timer.audio||new(window.AudioContext||window.webkitAudioContext)();timer.audio.resume();}catch(e){}timer.running=true;timer.end=Date.now()+timer.remaining*1000;timer.id=setInterval(tick,250);paintTimer();}if($('modal').open&&$('timerNumber'))teacher();}
 document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value.slice(0,3000);save();}if(el.dataset.profile!==undefined){state[el.dataset.profile]=el.value;save();}if(el.matches('[data-water]')){state.water=+el.value;updateWater();}if(el.matches('[data-future]')){state.future=+el.value;$('futureValue').textContent=state.future+'%';VillageScene.set(state);}if(el.matches('[data-strength]')){state.strength=+el.value;save();render();}});
 function updateWater(){const f=C.floodState(state.water,state.buildings);if($('waterValue'))$('waterValue').textContent=state.water+'단계';if($('waterLevel'))$('waterLevel').value=state.water;if($('waterStatus'))$('waterStatus').textContent=state.water+'단계 / 10단계';if($('wetBuildings'))$('wetBuildings').textContent=f.flooded;if($('floodStatus'))$('floodStatus').textContent='침수 건물 '+f.flooded+'개';document.querySelectorAll('[data-water-step]').forEach(b=>b.disabled=+b.dataset.waterStep>0?state.water>=10:state.water<=0);VillageScene.set(state);save();}
 document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.go){go(d.go);return;}if('close'in d){$('modal').close();return;}if('guide'in d){guide();return;}if('record'in d){record();return;}if('sources'in d){sources();return;}if(d.caseTab){state.caseTab=d.caseTab;render();return;}if(d.hazard){state.hazard=d.hazard;save();render();return;}if(d.topic!==undefined){state.topic=+d.topic;state.recent=null;state.actionTab='choose';render();return;}if(d.actionTab){state.actionTab=d.actionTab;render();return;}if(d.action){addAction(+d.action);return;}if(d.allActions){const level=+d.allActions;if(state.events.length>114){toast('남은 횟수가 6회보다 적어요. 행동을 하나씩 선택해 주세요.');return;}for(let i=0;i<6;i++)state.events.push({topic:i,level,id:'preset-'+Date.now()+'-'+i});state.topic=3;state.recent={topic:3,level,at:performance.now()};save();render();return;}if(d.futureHazard){state.futureHazard=d.futureHazard;render();return;}if('undoAction'in d){state.events.pop();state.recent=null;save();render();return;}if('resetActions'in d){showModal(modalTop('NEW EXPERIMENT','행동 실험을 새로 시작할까요?')+'<p>누적 행동 '+state.events.length+'회를 비웁니다. 다른 탐구 기록과 담아 둔 증거는 남습니다.</p><div class="btn-row"><button class="outline" data-close>계속 탐구하기</button><button class="primary" id="confirmResetActions">행동만 비우기</button></div>');$('confirmResetActions').onclick=()=>{state.events=[];state.recent=null;save();render();$('modal').close();};return;}if(d.evidence){addEvidence(d.evidence);return;}if(d.complete){if(!state.done.includes(d.complete))state.done.push(d.complete);save();render();toast('탐구 완료 표시를 남겼어요. 기록은 계속 수정할 수 있어요.');return;}if(d.world){state.world=d.world;if(!state.worldSeen.includes(d.world))state.worldSeen.push(d.world);save();render();return;}if(d.place){state.place=d.place;if(state.view==='phenomena'){state.view='life';state.strength=3;}save();render();return;}if('buildingPicker'in d){buildingPicker();return;}if(d.buildingType){if(!B.PLACEABLE.includes(d.buildingType))return;state.selectedBuilding=d.buildingType;state.seaTool=d.buildingType;save();$('modal').close();render();toast(B.TYPES[d.buildingType].name+' 선택 · 모형의 땅을 눌러 놓으세요.');return;}if('toggleBuildingNames'in d){state.showBuildingNames=!state.showBuildingNames;save();render();return;}if(d.seaTool){state.seaTool=d.seaTool;if(B.PLACEABLE.includes(d.seaTool))state.selectedBuilding=d.seaTool;save();render();return;}if(d.waterStep){state.water=C.clamp(state.water+(+d.waterStep),0,10);updateWater();return;}if('seaRun'in d){const f=C.floodState(state.water,state.buildings);state.seaRuns.push({water:state.water,flooded:f.flooded,total:f.total,layout:state.buildings.length+'개 배치'});state.seaRuns=state.seaRuns.slice(-30);save();render();toast('이 높이의 관찰값을 기록했어요.');return;}if('removeBuilding'in d){if(state.buildings.length)state.buildings.pop();save();render();return;}if('resetSea'in d){state.water=0;state.buildings=B.normalize(C.BASE_BUILDINGS);state.seaTool='orbit';VillageScene.reset();save();render();toast('모형을 처음 배치로 되돌렸어요. 관찰 기록은 남아 있어요.');return;}if(d.zoom){VillageScene.zoom(+d.zoom);return;}if('cameraReset'in d){VillageScene.reset();return;}if('seaCause'in d){cause();return;}if('discussion'in d){discussion();return;}if(d.worldPhoto){worldPhotoModal(d.worldPhoto);return;}if(d.photo){const c=CASES.find(c=>c.id===d.photo);showModal(modalTop('REAL PHOTOGRAPH',c.name+' 실제 사진')+'<img class="image-modal" src="assets/'+esc(c.photo.filename)+'" alt="'+esc(c.photo.alt_ko)+'"><p>'+esc(c.photo.caption_ko)+'</p><p class="caption">'+esc(c.photo.context_note_ko)+'<br>'+esc(c.photo.display_creator)+' · '+esc(c.photo.license)+'</p><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="'+esc(c.photo.source_url)+'">사진 원본과 저작자 정보 ↗</a></div>');return;}if(d.csv){const c=CASES.find(c=>c.id===d.csv),v=c.datasets[0];download(new Blob(['\ufeff자료,지역·기간,수치,단위\r\n'+v.labels.map((l,i)=>[v.title,l,v.values[i],v.unit].map(s=>'"'+String(s).replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),c.name+'_관측자료.csv');return;}if('deleteEvidence'in d){state.evidence=state.evidence.filter(x=>x.id!==d.deleteEvidence);save();renderNav();record();return;}if('exportPng'in d){exportPNG().catch(()=>toast('이미지 저장을 마치지 못했어요. 인쇄·PDF 저장을 이용해 주세요.'));return;}if('exportJson'in d){exportJSON();return;}if('importJson'in d){importJSON();return;}if('print'in d){window.print();return;}if('timerSet'in d){clearInterval(timer.id);timer.running=false;timer.remaining=timer.initial=+d.timerSet;paintTimer();teacher();return;}if('timerToggle'in d){toggleTimer();return;}if('timerReset'in d){clearInterval(timer.id);timer.running=false;timer.remaining=timer.initial;paintTimer();teacher();return;}if('fullscreen'in d){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>toast('브라우저 메뉴에서 전체화면을 사용할 수 있어요.'));else document.exitFullscreen?.();return;}if('lifeCompare'in d){const was=state.strength;state.strength=state.strength===3?1:3;save();render();toast(state.strength===1?'현상이 약한 가상 장면이에요. 다시 누르면 심한 장면으로 돌아와요.':'현상이 심한 가상 장면이에요.');return;}});
 window.addEventListener('village-place',e=>{if(state.view!=='sea'||!B.PLACEABLE.includes(state.seaTool))return;if(state.buildings.length>=24){toast('건물은 24개까지 놓을 수 있어요.');return;}const {x,z}=e.detail,candidate=B.create(state.seaTool,x,z,'added-'+Date.now());if(!candidate)return;if(C.terrain(candidate.x,candidate.z)<.06){toast('처음부터 바다였던 곳이에요. 땅을 눌러 배치해 주세요.');return;}if(state.buildings.some(b=>B.overlaps(b,candidate))){toast('건물이 겹치지 않도록 조금 더 넓은 땅을 골라 주세요.');return;}state.buildings.push(candidate);save();render();toast(candidate.name+' 배치 완료 · 물을 높여 바닥이 잠기는지 관찰해요.');});

 $('guideBtn').onclick=guide;$('teacherBtn').onclick=teacher;$('recordBtn').onclick=record;$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
 render();window.ClimateApp={getState:()=>JSON.parse(JSON.stringify(state)),go,exportPNG,normalize};
})();
